// diff = "diff", dong = "lines", them = "added", xoa = "removed", tep = "files", duocSua = "allowed to change"
const diff = [
  "--- a/gia-tien.js",
  "+++ b/gia-tien.js",
  "@@ -3,1 +3,2 @@",
  "-  return tong;",
  "+  return Math.floor(tong / 1000) * 1000;",
  "+  // round",
  "--- a/nut-gui.js",
  "+++ b/nut-gui.js",
  "@@ -10,1 +10,2 @@",
  "-  nut.onclick = null;",
  "+  nut.onclick = guiDon;",
  "+  nut.disabled = false;",
];
const duocSua = ["nut-gui.js"];

function phanTich(dong) {
  let them = 0;
  let xoa = 0;
  const tep = [];
  for (const d of dong) {
    if (d.startsWith("+++")) tep.push(d.slice(6));
    else if (d.startsWith("---")) continue;
    else if (d.startsWith("+")) them++;
    else if (d.startsWith("-")) xoa++;
  }
  return { them, xoa, tep };
}

const kq = phanTich(diff);
console.log("Added " + kq.them + " lines, removed " + kq.xoa + " lines");
console.log("Changed files: " + kq.tep.join(", "));
console.log("Outside the scope: " + kq.tep.filter((t) => !duocSua.includes(t)).join(", "));
